insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-08-06','opgelost','Offertes','Verzenden zet het dossier meteen op Verzonden',
   'Bij het versturen van een offerte verschoof het dossier niet altijd mee en kreeg je soms een foutmelding over Bouw7. Nu gaat het dossier na het verzenden automatisch naar de status Verzonden, ook in Bouw7, en verhuist een aanvraag daarmee direct naar het Offertes-overzicht.');
